entries[116184] = { ["name"] = "War Mill, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to build a War Mill building in your Garrison.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nSell Price:" }
entries[116185] = { ["name"] = "War Mill, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your War Mill building to level 2.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
entries[116186] = { ["name"] = "War Mill, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your War Mill building to level 3.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nRequires Achievement: Filling The Ranks\nSell Price:" }
