entries[116196] = { ["name"] = "Spirit Lodge, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Spirit Lodge building to level 2.\n\nLevel 1\nAllows the collection of Ogre Waystones from Ogres on Draenor. These waystones can be used to power an Ogre Waygate of your choice on Draenor. Also occasionally triggers Runes of Power during combat.\n\nLevel 2\nUnlocks access to a second Ogre Waygate for a total of 2.\n\nLevel 3\nUnlocks access to a third Ogre Waygate for a total of 3.\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
entries[116197] = { ["name"] = "Spirit Lodge, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Spirit Lodge building to level 3.\n\nLevel 1\nAllows the collection of Ogre Waystones from Ogres on Draenor. These waystones can be used to power an Ogre Waygate of your choice on Draenor. Also occasionally triggers Runes of Power during combat.\n\nLevel 2\nUnlocks access to a second Ogre Waygate for a total of 2.\n\nLevel 3\nUnlocks access to a third Ogre Waygate for a total of 3.\nRequires Achievement: Finding Your Waystones\nSell Price:" }
