entries[116247] = { ["name"] = "Frostwall Mines", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to build the Frostwall Mines.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus. Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes. In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\nSell Price:" }
entries[116248] = { ["name"] = "Frostwall Mines, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Frostwall Mines to level 2.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus. Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes. In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\nRequires Mine\nSell Price:" }
entries[116249] = { ["name"] = "Frostwall Mines, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Frostwall Mines to level 3.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus. Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes. In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\nRequires Achievement: Draenic Stone Collector\nSell Price:" }
