entries[116431] = { ["name"] = "Frostwall Tavern, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Frostwall Tavern building to level 2.\n\nLevel 1\nEach day, a visitor offering a dungeon quest with generous rewards will spend the day at your inn.\n\nLevel 2\nRecruits random followers each week. You can specify traits and abilities you're especially interested in.\n\nLevel 3\nUnlocks the particularly lucrative garrison resource missions.\nRequires Spires of Arak Outpost questline or level 35.\nSell Price:" }
entries[116432] = { ["name"] = "Frostwall Tavern, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to upgrade your Frostwall Tavern building to level 3.\n\nLevel 1\nEach day, a visitor offering a dungeon quest with generous rewards will spend the day at your inn.\n\nLevel 2\nRecruits random followers each week. You can specify traits and abilities you're especially interested in.\n\nLevel 3\nUnlocks the particularly lucrative garrison resource missions.\nRequires Achievement: Stay Awhile, And Listen\nSell Price:" }
entries[116433] = { ["name"] = "Frostwall Tavern, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Horde race\nUse: Provides the plans needed to build a Frostwall Tavern building in your Garrison.\n\nLevel 1\nEach day, a visitor offering a dungeon quest with generous rewards will spend the day at your inn.\n\nLevel 2\nRecruits random followers each week. You can specify traits and abilities you're especially interested in.\n\nLevel 3\nUnlocks the particularly lucrative garrison resource missions.\nSell Price:" }
