entries[116747] = { ["name"] = "Page from Nat's Fishing Journal", ["text"] = "Quest Item\n\"Ripped directly from Nat's private fishing journal.\"" }
entries[116748] = { ["name"] = "Fire Ammonite Lunker", ["text"] = "Quest Item\n\"A magical \"fish\" that lives in lava and looks like a squid in a cone shaped shell. Only caught by masterful anglers with the help of Nat Pagle.\"\nSell Price:" }
entries[116749] = { ["name"] = "Blackwater Whiptail Lunker", ["text"] = "Quest Item\n\"Has a powerful tail, which it uses to stun its prey. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[116750] = { ["name"] = "Blind Lake Sturgeon Lunker", ["text"] = "Quest Item\n\"Lacking eyes, it \"sees\" with its long whiskers. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[116751] = { ["name"] = "Abyssal Gulper Lunker", ["text"] = "Quest Item\n\"With a ridiculously oversized head and mouth, it can swallow prey bigger than itself. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[116752] = { ["name"] = "Jawless Skulker Lunker", ["text"] = "Quest Item\n\"A strange fish with no mouth and an unforked tail. Subsists on the life energy of plants. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[116753] = { ["name"] = "Fat Sleeper Lunker", ["text"] = "Quest Item\n\"Ugly and slimy. Surprisingly delicious when cooked. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[116754] = { ["name"] = "Molten Catfish", ["text"] = "Quest Item\n\"A prime example of Draenor fish species.\"" }
entries[116755] = { ["name"] = "Nat's Hookshot", ["text"] = "Quest Item\nUse: Attaches Nat's Hookshot lure to your fishing pole." }
entries[116756] = { ["name"] = "Stout Alemental", ["text"] = "Use: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Stout Alemental.\nRequires level 1 to 80 ( 80)" }
entries[116757] = { ["name"] = "Steamworks Sausage Grill", ["text"] = "Binds when picked up\nToy\nUse: Places a Steamworks Sausage Grill that increases the spirits of those nearby by 4 and allows cooking. (30 Min Cooldown)" }
entries[116758] = { ["name"] = "Brewfest Banner", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Represent Brewfest! (2 Hrs Cooldown)" }
entries[116759] = { ["name"] = "Blixthraz's Frightening Grudgesolver", ["text"] = "Quest Item\nUse: Blow up a Gentle Clefthoof. (3 Sec Cooldown)\n\"Model Designation: BFG9K-1\"" }
