entries[116766] = { ["name"] = "Apexis Keystone", ["text"] = "Quest Item\nUnique (4)\n\"This stone glows brightly, and is covered with symmetrical runes.\"" }
entries[116767] = { ["name"] = "Sapphire Riverbeast", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Sapphire Riverbeast.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This animal's color mimics the clear blue of Draenor's river shallows, making it almost invisible to aquatic predators.\"\nDrop:\nSilthide\nZone:\nTalador" }
entries[116768] = { ["name"] = "Mosshide Riverwallow", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Mosshide Riverwallow.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Aggressive and territorial, the mosshide is known for hiding in river-shore scrub and ambushing unwary passersby.\"\nVendor:\nDawn-Seeker Krek / Dawn-Seeker Alkset\nLocation:\nStormshield / Warspear\nCost:\n50, + 5,000" }
entries[116769] = { ["name"] = "Mudback Riverbeast", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Mudback Riverbeast.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Special webbing that grows on the soles of the mudback's feet gives them extra traction in mud and slick terrain.\"\nGarrison Mission:\nIt's a Boat, It's a Plane, It's... Just a Riverbeast." }
entries[116771] = { ["name"] = "Solar Spirehawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Solar Spirehawk.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Looking into the eyes of this mystical beast is like peering into the heart of the sun. Goggles are recommended when you're riding.\"\nDrop:\nRukhmar" }
entries[116772] = { ["name"] = "Shadowmane Charger", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Shadowmane Charger.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Arakkoa Outcasts\n- Exalted\nSell Price:\n\"Draenei poets have likened this talbuk's coloring to shadows cast by moonlight in an ashen forest.\"\nVendor:\nRavenspeaker Skeega / Shadow-Sage Brakoss\nFaction:\nArakkoa Outcasts - Exalted\nLocation:\nStormshield / Warspear\nCost:\n5, + 5,000" }
entries[116773] = { ["name"] = "Swift Breezestrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Swift Breezestrider.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Draenei have relied on this mount, the swiftest of all talbuk, to relay messengers and their missives safely to their destinations.\"\nDrop:\nPathrunner\nZone:\nShadowmoon Valley" }
entries[116774] = { ["name"] = "Trained Silverpelt", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Trained Silverpelt.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Prized for its intelligence, this breed of talbuk can be trained to execute defensive kicks and gorings in battle.\"\nLocation:\nGarrison Stables" }
entries[116775] = { ["name"] = "Breezestrider Stallion", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Breezestrider Stallion.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Vol'jin's Spear\n- Exalted\nSell Price:\n\"These breezestriders' red coloration reflects their temperament: sanguine, fierce, and courageous.\"\nVendor:\nDazzerian\nFaction:\nVol'jin's Spear - Exalted\nLocation:\nWarspear\nCost:\n5, + 5,000" }
entries[116776] = { ["name"] = "Pale Thorngrazer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Pale Thorngrazer.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Wrynn's Vanguard\n- Exalted\nSell Price:\n\"This talbuk subsists completely on a diet of thistles and thorns, making its insides as tough as its outside.\"\nVendor:\nCrafticus Mindbender\nFaction:\nWrynn's Vanguard - Exalted\nLocation:\nStormshield\nCost:\n5, + 5,000" }
entries[116777] = { ["name"] = "Vicious War Ram", ["text"] = "Binds to Warband\nMount\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Ram.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Until it head-butts you below the belt, it has not truly accepted you as its rider.\"\nVendor:\nNecrolord Sipe\nZone:\nStormwind City\nCost:\n1" }
entries[116778] = { ["name"] = "Vicious War Raptor", ["text"] = "Binds to Warband\nMount\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Raptor.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Because sharp teeth and claws weren't enough.\"\nVendor:\nDeathguard Netharian\nZone:\nOrgrimmar\nCost:\n1" }
entries[116779] = { ["name"] = "Garn Steelmaw", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Garn Steelmaw.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A trainer once tried to put decorative metal in his steelmaw wolf's mouth. He had to wait three days to get it back.\"\nDrop:\nInvader's Forgotten Treasure" }
entries[116780] = { ["name"] = "Warsong Direfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Warsong Direfang.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Has a will of iron but is a sweetheart if you give it a clefthoof bone to chew on.\"\nDrop:\nVengeance, Deathtalon, Terrorfist, Doomroller\nZone:\nTanaan Jungle" }
entries[116781] = { ["name"] = "Armored Frostwolf", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Armored Frostwolf.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It's trained to survive the harsh climate of Frostfire Ridge, so it snuggles as if its life depended on it.\"\nAchievement:\nThe Stable Master" }
entries[116782] = { ["name"] = "Ironside Warwolf", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Ironside Warwolf.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Laughing Skull Orcs\n- Exalted\nSell Price:\n\"It has an armored spike on its tail. Scratch its belly at your own risk.\"\nVendor:\nKil'rip\nFaction:\nLaughing Skull - Exalted\nLocation:\nHorde Garrison Trading Post\nCost:\n5, + 5,000" }
entries[116784] = { ["name"] = "Trained Snarler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Trained Snarler.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Enormously cute as a puppy. Slightly less so now.\"\nQuest:\nGarrison Stables" }
entries[116785] = { ["name"] = "Swift Frostwolf", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Swift Frostwolf.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Frostwolf Orcs\n- Exalted\nSell Price:\n\"Amidst the cold heights of Frostfire, the frostwolves hunt anything they can catch. The fastest among them eat well.\"\nVendor:\nBeska Redtusk\nFaction:\nFrostwolf Orcs - Exalted\nLocation:\nWarspear\nCost:\n5, + 5,000" }
entries[116786] = { ["name"] = "Smoky Direwolf", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Smoky Direwolf.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Believed to reside mostly in the north. Hates weddings.\"\nDrop:\nInvader's Forgotten Treasure" }
entries[116788] = { ["name"] = "Warlord's Deathwheel", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Warlord's Deathwheel.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Often referred to as the \"Goblin Lawn Mower\", this growling behemoth treats enemies like they are made of grass... ready to be mown down.\"\nAchievement:\nCategory:\nFeats of Strength" }
entries[116789] = { ["name"] = "Champion's Treadblade", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Champion's Treadblade.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Forged by human, gnome, and dwarf, this armored masterpiece is designed to slice a tauren into a tri-tip dinner with a flick of the handlebars.\"\nVendor:\nPaulie\nZone:\nStormwind, Old Town\nCost:" }
entries[116791] = { ["name"] = "Challenger's War Yeti", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Challenger's War Yeti.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Thankfully they move fast and mostly leave the smell behind them.\"\nAchievement:\nChallenge Warlord: Silver" }
entries[116792] = { ["name"] = "Sunhide Gronnling", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Sunhide Gronnling.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Loves the sun, hates everything else.\"\nDrop:\nPoundfist\nZone:\nGorgrond" }
entries[116794] = { ["name"] = "Garn Nighthowl", ["text"] = "Mount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Garn Nighthowl.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The garn are the most fierce predators on Draenor, and always hunt in packs.\"\nDrop:\nNok-Karosh\nLocation:\nFrostfire Ridge" }
